commands.command:
set -eu
git fetch origin work/ux-evolution
test "$(git rev-parse HEAD)" = "$(git rev-parse origin/work/ux-evolution)"
test -z "$(git status --porcelain)"
python3 - <<'PY'
from pathlib import Path
p=Path('apps/mobile/src/features/thermometers/components/SensorRemovalBlockedModal.tsx')
s=p.read_text()
assert s.count("import { IonButton } from '@ionic/react';")==1
s=s.replace("import { useTranslation } from '../../../app/i18n.js';", "import { useTranslation } from '../../../app/i18n.js';\nimport './SensorRemovalModal.css';")
old='''        <button
          className="secondary-action secondary-action--danger"
          type="button"
          title={t('hardware.sensor.deleteTitle')}
          onClick={onConfirm}
        >
          {t('common.delete')}
        </button>'''
new='''        <IonButton
          className="sensor-removal-danger-action"
          fill="outline"
          type="button"
          title={t('hardware.sensor.deleteTitle')}
          onClick={onConfirm}
        >
          {t('common.delete')}
        </IonButton>'''
assert s.count(old)==1
p.write_text(s.replace(old,new))
css=Path('apps/mobile/src/features/thermometers/components/SensorRemovalModal.css')
assert not css.exists()
css.write_text('''.sensor-removal-danger-action {
  --border-color: var(--lcl-color-status-danger-border);
  --border-radius: var(--lcl-radius-md);
  --border-style: solid;
  --border-width: var(--lcl-border-width-sm);
  --box-shadow: none;
  --color: var(--lcl-color-status-danger-text);
  min-height: var(--lcl-size-control-min-height);
  text-transform: none;
}
''')
p=Path('apps/mobile/src/features/thermometers/components/SensorRemovalBlockedModal.test.tsx')
s=p.read_text()
a="import { I18nProvider, setLocalePreference } from '../../../app/i18n.js';"
b="import { I18nProvider, setLocalePreference, t } from '../../../app/i18n.js';\nimport { getIonicButton } from '../../../test/ionicTestEvents.js';"
assert s.count(a)==1
s=s.replace(a,b)
s=s.replace("import { cleanup, fireEvent, render, screen } from '@testing-library/react';","import { cleanup, fireEvent, render, screen, within } from '@testing-library/react';")
s=s.replace("import { SensorRemovalBlockedModal } from './SensorRemovalBlockedModal.js';","import {\n  SensorRemovalBlockedModal,\n  SensorRemovalConfirmModal\n} from './SensorRemovalBlockedModal.js';")
marker="  it('keeps removal blocked and passes the exact owning installation id', () => {"
assert s.count(marker)==1
test='''  it('requires explicit Ionic Delete after opening confirmation and never deletes on Cancel', () => {
    const onClose = vi.fn();
    const onConfirm = vi.fn();
    const { rerender } = render(
      <I18nProvider>
        <SensorRemovalConfirmModal
          deviceName="Thermometer A"
          onClose={onClose}
          onConfirm={onConfirm}
        />
      </I18nProvider>
    );

    const dialog = screen.getByRole('dialog', {
      name: t('hardware.sensor.deleteConfirmTitle')
    });
    expect(dialog).toHaveTextContent('Thermometer A');
    expect(onConfirm).not.toHaveBeenCalled();
    const button = getIonicButton(dialog, t('common.delete'));
    expect(button).toHaveClass('sensor-removal-danger-action');
    expect(button).toHaveAttribute('title', t('hardware.sensor.deleteTitle'));
    fireEvent.click(within(dialog).getByRole('button', { name: t('common.cancel') }));
    expect(onClose).toHaveBeenCalledOnce();
    expect(onConfirm).not.toHaveBeenCalled();
    fireEvent.click(button);
    expect(onConfirm).toHaveBeenCalledOnce();

    rerender(
      <I18nProvider>
        <SensorRemovalConfirmModal
          deviceName={null}
          onClose={onClose}
          onConfirm={onConfirm}
        />
      </I18nProvider>
    );
    expect(screen.queryByRole('dialog')).toBeNull();
    expect(onConfirm).toHaveBeenCalledOnce();
  });

'''
s=s.replace(marker,test+marker)
p.write_text(s)
PY
pnpm exec prettier --write apps/mobile/src/features/thermometers/components/SensorRemovalBlockedModal.tsx apps/mobile/src/features/thermometers/components/SensorRemovalModal.css apps/mobile/src/features/thermometers/components/SensorRemovalBlockedModal.test.tsx
git diff --check
pnpm --filter @lcl/mobile exec vitest run src/features/thermometers/components/SensorRemovalBlockedModal.test.tsx src/features/plugs/components/PlugDeleteConfirmModal.test.tsx src/__tests__/modal.test.tsx --reporter=default
pnpm --filter @lcl/mobile typecheck
git add apps/mobile/src/features/thermometers/components/SensorRemovalBlockedModal.tsx apps/mobile/src/features/thermometers/components/SensorRemovalModal.css apps/mobile/src/features/thermometers/components/SensorRemovalBlockedModal.test.tsx
git commit -m "refactor(ionic): migrate guarded thermometer delete confirmation"
git push origin HEAD:refs/heads/work/ux-evolution
echo "MIGRATION_COMMIT=$(git rev-parse HEAD)"
git status --short
